#!/usr/bin/env sh
# fetch STA — altoadigemobilità/Südtirolmobil (incl. SASA Bolzano/Merano urban + SAD/regional extra-urban + rail + cable cars) (IT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://gtfs.api.opendatahub.com/v1/dataset/sta-time-tables/raw"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
